use axum::{routing::get, Router, http::StatusCode};
use std::time::Duration;

async fn ready(pool: &Pool) -> StatusCode {
    match tokio::time::timeout(Duration::from_millis(200), pool.ping()).await {
        Ok(Ok(())) => StatusCode::OK,
        _ => StatusCode::SERVICE_UNAVAILABLE,
    }
}

let app = Router::new()
    .route("/healthz/live", get(|| async { StatusCode::OK }))
    .route("/healthz/ready", get(|| async { ready(&pool).await }))
    .with_state(pool.clone());

